import{finite}from'./algorithms.mjs';
export function aggregateOverviewTrends(rows){const groups=new Map();for(const r of rows){if(r.flow_kind!=='production'||!/^\d{4}-\d{2}-\d{2}$/.test(String(r.date)))continue;const month=r.date.slice(0,7),g=groups.get(month)??{month,oil:[],water:[],pairedOil:0,pairedGas:0,gorPairs:0,pressureWeighted:0,pressureHours:0,pressureCount:0};if(finite(r.oil_volume_sm3))g.oil.push(Number(r.oil_volume_sm3));if(finite(r.water_volume_sm3))g.water.push(Number(r.water_volume_sm3));if(finite(r.oil_volume_sm3)&&finite(r.gas_volume_sm3)&&r.oil_volume_sm3>=0&&r.gas_volume_sm3>=0){g.pairedOil+=Number(r.oil_volume_sm3);g.pairedGas+=Number(r.gas_volume_sm3);g.gorPairs++;}const p=r.pressure_for_model_source_unit??r.AVG_DOWNHOLE_PRESSURE,h=r.on_stream_hours;if(finite(p)&&p>0&&finite(h)&&h>0&&h<=24.01){g.pressureWeighted+=Number(p)*Number(h);g.pressureHours+=Number(h);g.pressureCount++;}groups.set(month,g);}return[...groups.values()].sort((a,b)=>a.month.localeCompare(b.month)).map(g=>({month:g.month,oil_volume_sm3:g.oil.length?g.oil.reduce((a,b)=>a+b,0):null,water_volume_sm3:g.water.length?g.water.reduce((a,b)=>a+b,0):null,pressure_source_unit:g.pressureHours?g.pressureWeighted/g.pressureHours:null,pressure_sample_count:g.pressureCount,pressure_weight_hours:g.pressureHours,gor_sm3_per_sm3:g.pairedOil>0?g.pairedGas/g.pairedOil:null,gor_pair_count:g.gorPairs,gor_paired_oil_sm3:g.pairedOil,gor_paired_gas_sm3:g.pairedGas}));}
